import{_ as o,o as a,c as r,ai as p}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"ERP 企业资源计划 · OpenBiz 第五个独立消费者","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/erp.md","filePath":"apps/openbiz/erp.md"}'),i={name:"apps/openbiz/erp.md"};function c(n,e,d,t,l,s){return a(),r("div",null,[...e[0]||(e[0]=[p('<h1 id="erp-企业资源计划-·-openbiz-第五个独立消费者" tabindex="-1">ERP 企业资源计划 · OpenBiz 第五个独立消费者 <a class="header-anchor" href="#erp-企业资源计划-·-openbiz-第五个独立消费者" aria-label="Permalink to “ERP 企业资源计划 · OpenBiz 第五个独立消费者”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-erp-app</code>（<code>E:/8.cangku/for-job/openbiz-erp-app</code>）：独立后端（端口 18085）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_erp</code>。</p></blockquote><blockquote><p>实证：OpenBiz shop 域有 Inventory CAS、business 域有 Order，但采购 / 供应商需自建。按 OpenBiz 命名约定自建 <code>openbiz_erp_*</code> 表，在其多租户基座之上实现「供应商 + 采购单」最小闭环与单据状态机。验证「百套流水线」对 A 类工程量最大系统（第 3 个）的可复制性。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户、<code>ruoyi-framework</code> 基础能力</li><li><strong>自建</strong>：<code>openbiz_erp_supplier</code> / <code>openbiz_erp_purchase_order</code> 表 + Mapper / Service / Controller <ul><li>供应商状态机：<code>ACTIVE ⇄ FROZEN</code>，二者均可 <code>→ BLOCKED</code>（终态）；BLOCKED 解冻被拒</li><li>采购单状态机：<code>DRAFT → SUBMITTED → APPROVED → ORDERED → RECEIVED</code>（终态）；<code>CANCELLED</code> 仅 DRAFT/SUBMITTED 可转；RECEIVED 后任何跳转均被拒</li><li>统计：<code>GET /api/erp/purchase/stats</code> 返回完整三段（PLANNING/EXECUTING/CLOSED，缺段补 0）</li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>登录 → 建供应商(ACTIVE) → 冻结/解冻闭环 → 建采购单(DRAFT) → 提交 → 审批 → 下单 → 收货(RECEIVED) → 各阶段统计正确 → RECEIVED 后取消 / BLOCKED 后解冻均被拦截 <code>ILLEGAL_TRANSITION</code> → 数据落库可重拉。</p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-erp-app</code>（端口 18085，含 README 与 E2E 脚本）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>工程量最大的 A 类系统（采购 / 供应商 / 订单单据链）同样可在 OpenBiz 基座上以独立消费者方式快速落地，进一步证明底座通用性。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',13)])])}const b=o(i,[["render",c]]);export{h as __pageData,b as default};
